<template>
	<NodeViewWrapper data-text-el="table-header" as="th" :dir="dir" :style="align">
		<div>
			<NodeViewContent class="content" />
			<NcActions
				v-if="isEditable"
				ref="menu"
				size="small"
				variant="tertiary-no-background"
				data-text-table-actions="header">
				<NcActionButtonGroup>
					<NcActionButton
						data-text-table-action="align-column-left"
						:aria-label="t('text', 'Left align column')"
						type="radio"
						value="left"
						:model-value="node.attrs.align"
						@click="setAlignLeft">
						<template #icon>
							<AlignHorizontalLeft />
						</template>
					</NcActionButton>
					<NcActionButton
						data-text-table-action="align-column-center"
						:aria-label="t('text', 'Center align column')"
						type="radio"
						value="center"
						:model-value="node.attrs.align"
						@click="setAlignCenter">
						<template #icon>
							<AlignHorizontalCenter />
						</template>
					</NcActionButton>
					<NcActionButton
						data-text-table-action="align-column-right"
						:aria-label="t('text', 'Right align column')"
						type="radio"
						value="right"
						:model-value="node.attrs.align"
						@click="setAlignRight">
						<template #icon>
							<AlignHorizontalRight />
						</template>
					</NcActionButton>
				</NcActionButtonGroup>
				<NcActionButton
					data-text-table-action="sort-column-asc"
					close-after-click
					@click="sortColumnAsc">
					<template #icon>
						<SortAscending />
					</template>
					{{ t('text', 'Sort ascending') }}
				</NcActionButton>
				<NcActionButton
					data-text-table-action="sort-column-desc"
					close-after-click
					@click="sortColumnDesc">
					<template #icon>
						<SortDescending />
					</template>
					{{ t('text', 'Sort descending') }}
				</NcActionButton>
				<NcActionButton
					data-text-table-action="add-column-before"
					close-after-click
					@click="addColumnBefore">
					<template #icon>
						<TableAddColumnBefore />
					</template>
					{{ t('text', 'Add column before') }}
				</NcActionButton>
				<NcActionButton
					data-text-table-action="add-column-after"
					close-after-click
					@click="addColumnAfter">
					<template #icon>
						<TableAddColumnAfter />
					</template>
					{{ t('text', 'Add column after') }}
				</NcActionButton>
				<NcActionButton
					data-text-table-action="remove-column"
					close-after-click
					@click="deleteColumn">
					<template #icon>
						<TrashCan />
					</template>
					{{ t('text', 'Delete this column') }}
				</NcActionButton>
			</NcActions>
		</div>
	</NodeViewWrapper>
</template>

<script>
import { t } from '@nextcloud/l10n'
import NcActionButton from '@nextcloud/vue/components/NcActionButton'
import NcActionButtonGroup from '@nextcloud/vue/components/NcActionButtonGroup'
import NcActions from '@nextcloud/vue/components/NcActions'
import { NodeViewContent, NodeViewWrapper } from '@tiptap/vue-2'
import {
	AlignHorizontalCenter,
	AlignHorizontalLeft,
	AlignHorizontalRight,
	SortAscending,
	SortDescending,
	TableAddColumnAfter,
	TableAddColumnBefore,
	TrashCan,
} from '../../components/icons.js'

export default {
	name: 'TableHeaderView',
	components: {
		AlignHorizontalCenter,
		AlignHorizontalLeft,
		AlignHorizontalRight,
		TrashCan,
		NcActionButton,
		NcActionButtonGroup,
		NcActions,
		NodeViewWrapper,
		NodeViewContent,
		TableAddColumnBefore,
		TableAddColumnAfter,
		SortAscending,
		SortDescending,
	},
	props: {
		editor: {
			type: Object,
			required: true,
		},
		getPos: {
			type: Function,
			required: true,
		},
		node: {
			type: Object,
			required: true,
		},
	},
	data() {
		return {
			isEditable: false,
		}
	},
	computed: {
		align() {
			return { 'text-align': this.node.attrs.align }
		},
		dir() {
			return this.node.attrs.dir || ''
		},
	},
	beforeMount() {
		this.isEditable = this.editor.isEditable
		this.editor.on('update', ({ editor }) => {
			this.isEditable = editor.isEditable
		})
	},
	methods: {
		setAlignCenter() {
			this.setAlign('center')
		},
		setAlignLeft() {
			this.setAlign('left')
		},
		setAlignRight() {
			this.setAlign('right')
		},
		setAlign(align) {
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos())
				.setCellAttribute('align', align)
				.run()
			while (this.editor.commands.goToNextRow()) {
				this.editor.commands.setCellAttribute('align', align)
			}
			// Set focus back to first row
			this.editor.chain().setTextSelection(this.getPos()).focus().run()
			this.$refs.menu.closeMenu(false)
		},
		deleteColumn() {
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos())
				.deleteColumn()
				.run()
		},
		addColumnBefore() {
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos())
				.addColumnBefore()
				.run()
		},
		addColumnAfter() {
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos())
				.addColumnAfter()
				.run()
		},
		sortColumnAsc() {
			this.sortColumn('asc')
		},
		sortColumnDesc() {
			this.sortColumn('desc')
		},
		sortColumn(direction) {
			this.editor.commands.sortColumn(direction, this.node)
		},
		t,
	},
}
</script>

